      ]
    },
    {
      "instrument_id": "EQ15",
      "role": "primary",
      "technique": "Uniaxial constrained-recovery force testing (universal mechanical testing)",
      "why": "The Instron 5967 can hold a programmed polymer at a fixed extension or compression and directly record the recovery force generated upon activation, accommodating much larger samples and higher forces than a rheometer. However, because shape memory activation requires an external stimulus, you must confirm a compatible heating chamber or stimulus source.",
      "accessories_to_confirm": [
        "Load cell scaled to the expected recovery force",
        "Tensile grips or compression platens suitable for the polymer geometry",
        "Environmental/temperature chamber (or external heating/light activation setup compatible with the load frame)"
      ]
    },
